INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I001', 'scientific_wording', '{"type":"scientific_wording","source_statement":"酸素がミトコンドリアでエネルギー（ATP）に変わる","editorial_action":"酸素は、細胞が栄養からATPをつくる過程で使われます。","proposed_wording":"酸素は、細胞が栄養からATPをつくる過程で使われます。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P01"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I002', 'terminology', '{"type":"terminology","source_statement":"内呼吸（Cellular Respiration）","editorial_action":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。","proposed_wording":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P02"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I003', 'unsupported_quantity', '{"type":"unsupported_quantity","source_statement":"1分間にATPを約2〜3kg産生","editorial_action":"ATPの産生・利用は繰り返されています。原稿の「1分間に約2〜3kg」は根拠確認まで掲載しない。","proposed_wording":"ATPの産生・利用は繰り返されています。原稿の「1分間に約2〜3kg」は根拠確認まで掲載しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P07"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I004', 'overgeneralization', '{"type":"overgeneralization","source_statement":"すべての細胞でミトコンドリアがATPを作る","editorial_action":"多くの細胞では、ミトコンドリアがATPの産生に関わります。","proposed_wording":"多くの細胞では、ミトコンドリアがATPの産生に関わります。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P07"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I005', 'arithmetic', '{"type":"arithmetic","source_statement":"37兆個（37,000億個）","editorial_action":"37兆個（370,000億個）。※単位換算のみの修正案。37兆個という生物学的な数値の妥当性とは別。","proposed_wording":"37兆個（370,000億個）。※単位換算のみの修正案。37兆個という生物学的な数値の妥当性とは別。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P07"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I006', 'unsafe_scoring', '{"type":"unsafe_scoring","source_statement":"呼吸数8回以下をとても良いとする評価表","editorial_action":"安静時の呼吸数を記録し、そのときの状態と一緒に振り返りましょう。回数だけで「良い・悪い」を採点しません。","proposed_wording":"安静時の呼吸数を記録し、そのときの状態と一緒に振り返りましょう。回数だけで「良い・悪い」を採点しません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P08"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I007', 'overgeneralization', '{"type":"overgeneralization","source_statement":"CO₂がなければ呼吸できない／ヨガはCO₂耐性で心身を安定","editorial_action":"CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。","proposed_wording":"CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P06"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I008', 'citation_version', '{"type":"citation_version","source_statement":"引用先CYPにはシータリーが明記されている","editorial_action":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。","proposed_wording":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。","remaining_work":"引用元の特定・照合が必要"}', 'editorial_policy_applied', '["P19","P24"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I009', 'text_image_difference', '{"type":"text_image_difference","source_statement":"ブラーマリーのイラストは耳に手を当てるが簡易版の本文手順にはない","editorial_action":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。","proposed_wording":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P20"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I010', 'audience_conflict', '{"type":"audience_conflict","source_statement":"初心者の参考回数と、初心者は実践しないという教材方針が併記","editorial_action":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。","proposed_wording":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P21","P22"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I011', 'citation_scope', '{"type":"citation_scope","source_statement":"妊娠中・月経中をCYPのカパラバティ禁忌として列挙","editorial_action":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。","proposed_wording":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。","remaining_work":"引用元の特定・照合が必要"}', 'editorial_policy_applied', '["P22"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I012', 'protocol_variation', '{"type":"protocol_variation","source_statement":"4-7-8で保息を短縮または省略","editorial_action":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。","proposed_wording":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P25"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I013', 'efficacy_claim', '{"type":"efficacy_claim","source_statement":"睡眠・集中・免疫・健康寿命などの広い改善表現","editorial_action":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。","proposed_wording":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P10","P11","P24"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I014', 'product_copy', '{"type":"product_copy","source_statement":"AIが最適な改善提案／QRコード誘導","editorial_action":"QRとAIの紹介は案内欄に分ける。接続先・機能が確認できた範囲だけを説明する。","proposed_wording":"QRとAIの紹介は案内欄に分ける。接続先・機能が確認できた範囲だけを説明する。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P11"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I015', 'editorial_review', '{"type":"editorial_review","source_statement":"副鼻腔のNOから集中力・免疫・運動効果へつなげる説明","editorial_action":"副鼻腔の構造の説明を残し、集中力・免疫・運動能力への効果は根拠確認まで別欄で保留する。","proposed_wording":"副鼻腔の構造の説明を残し、集中力・免疫・運動能力への効果は根拠確認まで別欄で保留する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P031"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I016', 'editorial_review', '{"type":"editorial_review","source_statement":"吐くときは内肋間筋が収縮、という一律の図示","editorial_action":"安静時に吐く場合と、力を入れて吐く場合を分けて説明する。筋肉名と図の動作は監修後に確定する。","proposed_wording":"安静時に吐く場合と、力を入れて吐く場合を分けて説明する。筋肉名と図の動作は監修後に確定する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P036"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I017', 'source_numbering', '{"type":"source_numbering","source_statement":"第3章ファイル内に第2章・P12〜P20の表示がある","editorial_action":"ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。","proposed_wording":"ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。","remaining_work":"章番号・掲載画像の具体的な選択は未確定"}', 'editorial_policy_applied', '["P037","P038"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I018', 'editorial_review', '{"type":"editorial_review","source_statement":"深くゆっくり吸うほど効率がよいという一般化","editorial_action":"この図は、死腔と肺胞換気を理解するための計算例です。呼吸を大きくする練習の目標値ではありません。","proposed_wording":"この図は、死腔と肺胞換気を理解するための計算例です。呼吸を大きくする練習の目標値ではありません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P038"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I019', 'editorial_review', '{"type":"editorial_review","source_statement":"SpO₂の範囲だけで健康・軽い不調等を決める表","editorial_action":"SpO₂の数値だけで健康状態を採点しません。測定条件や症状も含めて扱います。","proposed_wording":"SpO₂の数値だけで健康状態を採点しません。測定条件や症状も含めて扱います。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P041"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I020', 'editorial_review', '{"type":"editorial_review","source_statement":"ATPは1日に体重の約100倍作られる","editorial_action":"ATPの再利用の説明を残し、「1日に体重の約100倍」の数値は根拠確認まで掲載しない。","proposed_wording":"ATPの再利用の説明を残し、「1日に体重の約100倍」の数値は根拠確認まで掲載しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P043"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I021', 'scientific_review', '{"type":"scientific_review","source_statement":"解糖をミトコンドリア内に配置／酸素がなければ糖はエネルギーにならない","editorial_action":"糖からエネルギーを取り出す過程は複数あります。反応の場所と酸素の必要性を分けた図に描き直し、監修を受ける。","proposed_wording":"糖からエネルギーを取り出す過程は複数あります。反応の場所と酸素の必要性を分けた図に描き直し、監修を受ける。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P044"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I022', 'timing_variants', '{"type":"timing_variants","source_statement":"第6章の図では呼気後に自然に待つ1〜2秒を追加し、回数換算の表記にも不一致がある","editorial_action":"基本手順と図中の「自然な間」を別記する。記載のない固定保息や毎分回数へ換算しない。","proposed_wording":"基本手順と図中の「自然な間」を別記する。記載のない固定保息や毎分回数へ換算しない。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P081"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I023', 'timing_variants', '{"type":"timing_variants","source_statement":"ボックス呼吸の回数は第6章4〜5、第7章3〜5。やさしい版は等間隔ではない","editorial_action":"第6章：4〜5サイクル。第7章：3〜5セット。やさしい版は別の変種。各出典の手順を独立して表示する。","proposed_wording":"第6章：4〜5サイクル。第7章：3〜5セット。やさしい版は別の変種。各出典の手順を独立して表示する。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P082","P083"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I024', 'attribution', '{"type":"attribution","source_statement":"ボックス呼吸をNavy SEALsが考案したという記載","editorial_action":"ボックス呼吸を現代呼吸法として紹介する。「Navy SEALsが考案」は起源資料が確認できるまで削除候補にする。","proposed_wording":"ボックス呼吸を現代呼吸法として紹介する。「Navy SEALsが考案」は起源資料が確認できるまで削除候補にする。","remaining_work":"引用元の特定・照合が必要"}', 'editorial_policy_applied', '["P082"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I025', 'ambiguous_instruction', '{"type":"ambiguous_instruction","source_statement":"4・7・8呼吸法に「7秒間、息を止めずにキープ」と記載","editorial_action":"「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。","proposed_wording":"「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P085"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I026', 'distinct_variant', '{"type":"distinct_variant","source_statement":"第8章の「4-7-8呼吸のやさしい版」は4秒吸う・7〜8秒吐く、保息なし","editorial_action":"名称案：就寝前のやさしい呼吸（第8章・保息なし）。原図の4秒吸う・7〜8秒吐くを記録し、7秒の保息は追加しない。","proposed_wording":"名称案：就寝前のやさしい呼吸（第8章・保息なし）。原図の4秒吸う・7〜8秒吐くを記録し、7秒の保息は追加しない。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P094"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I027', 'name_conflict', '{"type":"name_conflict","source_statement":"10-4の実践2見出しが「食前の休息呼吸」だが、手順は食後、第10章一覧も食後","editorial_action":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。","proposed_wording":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P105","P106"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I028', 'duplicate_layout', '{"type":"duplicate_layout","source_statement":"第13章に13-4の図版が2種類ある","editorial_action":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。","proposed_wording":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。","remaining_work":"章番号・掲載画像の具体的な選択は未確定"}', 'editorial_policy_applied', '["P112","P113"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I029', 'timing_variants', '{"type":"timing_variants","source_statement":"第14章は同名の基本技法と秒数・吐き方が異なる","editorial_action":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。","proposed_wording":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P107","P108","P117","P118"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I030', 'scientific_review', '{"type":"scientific_review","source_statement":"空気の経路に副鼻腔・血液・細胞を直列表示","editorial_action":"空気の通路と、肺胞から血液・細胞への酸素の運搬を2段に分けて図示する。副鼻腔を必須の直列通過点にしない。","proposed_wording":"空気の通路と、肺胞から血液・細胞への酸素の運搬を2段に分けて図示する。副鼻腔を必須の直列通過点にしない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P149"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I031', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"一回の呼吸は約0.5秒／図の0.9秒","editorial_action":"一呼吸の周期と肺まで空気が移動する時間を区別する。「約0.5秒」「0.9秒」は定義・根拠確認まで掲載しない。","proposed_wording":"一呼吸の周期と肺まで空気が移動する時間を区別する。「約0.5秒」「0.9秒」は定義・根拠確認まで掲載しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P151"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I032', 'scientific_review', '{"type":"scientific_review","source_statement":"肺には筋肉がありません／肺は動かない","editorial_action":"肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。","proposed_wording":"肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P152"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I033', 'scientific_review', '{"type":"scientific_review","source_statement":"肋骨運動の名称と方向、全肋骨が胸骨につながる図","editorial_action":"肋骨の動きの名称・方向・胸骨との接続先を監修し、図と本文を同時に修正する。","proposed_wording":"肋骨の動きの名称・方向・胸骨との接続先を監修し、図と本文を同時に修正する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P153"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I034', 'scientific_review', '{"type":"scientific_review","source_statement":"呼気時の胸腔内圧を一律に陽圧として表す","editorial_action":"図に圧の測定部位・基準・単位・呼吸条件を明記する。確認前は「呼気時の胸腔内圧は陽圧」という一律の説明を外す。","proposed_wording":"図に圧の測定部位・基準・単位・呼吸条件を明記する。確認前は「呼気時の胸腔内圧は陽圧」という一律の説明を外す。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P154","P155"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I035', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"SpO₂の章内の区分不一致","editorial_action":"章内のSpO₂区分表は回答用から外し、統一する医学的な基準・対象・条件を監修者に確認する。","proposed_wording":"章内のSpO₂区分表は回答用から外し、統一する医学的な基準・対象・条件を監修者に確認する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P158"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I036', 'scientific_review', '{"type":"scientific_review","source_statement":"酸素タクシーは満員で出発、細胞で全席空く","editorial_action":"酸素タクシーは、結合部位を学ぶためのたとえです。必ず満席で出発し、全部を降ろすという意味ではありません。","proposed_wording":"酸素タクシーは、結合部位を学ぶためのたとえです。必ず満席で出発し、全部を降ろすという意味ではありません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P163"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I037', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"肺胞数3〜5億と2億5000万の違い","editorial_action":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。","proposed_wording":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P156","P164"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I038', 'internal_arithmetic', '{"type":"internal_arithmetic","source_statement":"37兆個の細胞と37兆個のミトコンドリアの混同","editorial_action":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。","proposed_wording":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P168","P170"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I039', 'scientific_review', '{"type":"scientific_review","source_statement":"運動・呼吸・食品・栄養補助成分でミトコンドリアが増えるという一覧","editorial_action":"運動・睡眠・食事などの生活要素を紹介する。個別成分でミトコンドリアが増える、若返るという断定や摂取指示は掲載しない。","proposed_wording":"運動・睡眠・食事などの生活要素を紹介する。個別成分でミトコンドリアが増える、若返るという断定や摂取指示は掲載しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P171"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I040', 'scientific_review', '{"type":"scientific_review","source_statement":"疲労等のすべての原因はATP不足・低酸素","editorial_action":"この図だけで、本人の疲労や眠気の原因をATP不足・低酸素と判断することはできません。","proposed_wording":"この図だけで、本人の疲労や眠気の原因をATP不足・低酸素と判断することはできません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P159","P172","P211"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I041', 'scientific_review', '{"type":"scientific_review","source_statement":"吸気＝交感、呼気＝副交感の二値スイッチ／唯一・最も確実","editorial_action":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。","proposed_wording":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P180","P184","P185"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I042', 'scientific_review', '{"type":"scientific_review","source_statement":"グラフの「心拍（R-R間隔）」","editorial_action":"「心拍数」と「R-R間隔」を別の量として表示する。軸名・単位・波形の向きを確認して図を差し替える。","proposed_wording":"「心拍数」と「R-R間隔」を別の量として表示する。軸名・単位・波形の向きを確認して図を差し替える。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P185"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I043', 'citation_review', '{"type":"citation_review","source_statement":"Frontiers・NCBI・PMC・med.navy.mil等だけの引用","editorial_action":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。","proposed_wording":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。","remaining_work":"引用元の特定・照合が必要"}', 'editorial_policy_applied', '["P174","P183","P184","P187","P207"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I044', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"導入4-4-6〜8-4秒とボックス4-4-4-4秒の差","editorial_action":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。","proposed_wording":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P186","P187","P188"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I045', 'label_correction', '{"type":"label_correction","source_statement":"呼吸カウントの図3人目が吐いて1、本文は吸って2","editorial_action":"図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。","proposed_wording":"図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P197"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I046', 'classification_update', '{"type":"classification_update","source_statement":"NREM睡眠をステージ1〜4で記載","editorial_action":"NREM睡眠をN1・N2・N3の3段階に整理する。図の配置と本文をまとめて更新する。","proposed_wording":"NREM睡眠をN1・N2・N3の3段階に整理する。図の配置と本文をまとめて更新する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P206"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I047', 'scientific_review', '{"type":"scientific_review","source_statement":"NOから脳・免疫・いびき・睡眠への効果をつなぐ図","editorial_action":"鼻の構造・NOの説明と、脳・免疫・いびき・睡眠への効果の主張を別に扱う。効能の矢印は根拠確認まで保留する。","proposed_wording":"鼻の構造・NOの説明と、脳・免疫・いびき・睡眠への効果の主張を別に扱う。効能の矢印は根拠確認まで保留する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P196","P208"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I048', 'scientific_review', '{"type":"scientific_review","source_statement":"深呼吸で代謝・血流・老廃物排出・消化排泄が一律に改善","editorial_action":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。","proposed_wording":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P213","P215","P216"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I049', 'scientific_review', '{"type":"scientific_review","source_statement":"声の質のすべてが呼吸で決まる／胸・頭を共鳴腔として図示","editorial_action":"声は、呼吸・声帯・共鳴・発音などが関係して生まれます。胸や頭に感じる響きと、解剖学的な共鳴腔は区別して監修する。","proposed_wording":"声は、呼吸・声帯・共鳴・発音などが関係して生まれます。胸や頭に感じる響きと、解剖学的な共鳴腔は区別して監修する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P223"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I050', 'editorial_metadata', '{"type":"editorial_metadata","source_statement":"外部監修を入れる場合の配置候補","editorial_action":"「監修候補・未依頼」という制作メモとして保存する。教材本文やAIの回答に監修済みと表示しない。","proposed_wording":"「監修候補・未依頼」という制作メモとして保存する。教材本文やAIの回答に監修済みと表示しない。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', '["P224"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I051', 'terminology_review', '{"type":"terminology_review","source_statement":"アシュタンガの八支則と流派名の関係","editorial_action":"八支則を意味する用語としてのアシュタンガと、現代の実践スタイルの名称を分け、歴史・用語の監修後に確定する。","proposed_wording":"八支則を意味する用語としてのアシュタンガと、現代の実践スタイルの名称を分け、歴史・用語の監修後に確定する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', '["P231"]') ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC001', 'I001', '酸素は、細胞が栄養からATPをつくる過程で使われます。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC002', 'I002', '「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC003', 'I003', 'ATPの産生・利用は繰り返されています。原稿の「1分間に約2〜3kg」は根拠確認まで掲載しない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC004', 'I004', '多くの細胞では、ミトコンドリアがATPの産生に関わります。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC005', 'I005', '37兆個（370,000億個）。※単位換算のみの修正案。37兆個という生物学的な数値の妥当性とは別。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC006', 'I006', '安静時の呼吸数を記録し、そのときの状態と一緒に振り返りましょう。回数だけで「良い・悪い」を採点しません。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC007', 'I007', 'CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC008', 'I008', '引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC009', 'I009', '簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC010', 'I010', 'この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC011', 'I011', '該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC012', 'I012', '保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC013', 'I013', 'この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC014', 'I014', 'QRとAIの紹介は案内欄に分ける。接続先・機能が確認できた範囲だけを説明する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC015', 'I015', '副鼻腔の構造の説明を残し、集中力・免疫・運動能力への効果は根拠確認まで別欄で保留する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC016', 'I016', '安静時に吐く場合と、力を入れて吐く場合を分けて説明する。筋肉名と図の動作は監修後に確定する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC017', 'I017', 'ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC018', 'I018', 'この図は、死腔と肺胞換気を理解するための計算例です。呼吸を大きくする練習の目標値ではありません。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC019', 'I019', 'SpO₂の数値だけで健康状態を採点しません。測定条件や症状も含めて扱います。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC020', 'I020', 'ATPの再利用の説明を残し、「1日に体重の約100倍」の数値は根拠確認まで掲載しない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC021', 'I021', '糖からエネルギーを取り出す過程は複数あります。反応の場所と酸素の必要性を分けた図に描き直し、監修を受ける。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC022', 'I022', '基本手順と図中の「自然な間」を別記する。記載のない固定保息や毎分回数へ換算しない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC023', 'I023', '第6章：4〜5サイクル。第7章：3〜5セット。やさしい版は別の変種。各出典の手順を独立して表示する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC024', 'I024', 'ボックス呼吸を現代呼吸法として紹介する。「Navy SEALsが考案」は起源資料が確認できるまで削除候補にする。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC025', 'I025', '「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC026', 'I026', '名称案：就寝前のやさしい呼吸（第8章・保息なし）。原図の4秒吸う・7〜8秒吐くを記録し、7秒の保息は追加しない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC027', 'I027', '見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC028', 'I028', '13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC029', 'I029', '第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC030', 'I030', '空気の通路と、肺胞から血液・細胞への酸素の運搬を2段に分けて図示する。副鼻腔を必須の直列通過点にしない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC031', 'I031', '一呼吸の周期と肺まで空気が移動する時間を区別する。「約0.5秒」「0.9秒」は定義・根拠確認まで掲載しない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC032', 'I032', '肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC033', 'I033', '肋骨の動きの名称・方向・胸骨との接続先を監修し、図と本文を同時に修正する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC034', 'I034', '図に圧の測定部位・基準・単位・呼吸条件を明記する。確認前は「呼気時の胸腔内圧は陽圧」という一律の説明を外す。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC035', 'I035', '章内のSpO₂区分表は回答用から外し、統一する医学的な基準・対象・条件を監修者に確認する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC036', 'I036', '酸素タクシーは、結合部位を学ぶためのたとえです。必ず満席で出発し、全部を降ろすという意味ではありません。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC037', 'I037', '肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC038', 'I038', '細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC039', 'I039', '運動・睡眠・食事などの生活要素を紹介する。個別成分でミトコンドリアが増える、若返るという断定や摂取指示は掲載しない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC040', 'I040', 'この図だけで、本人の疲労や眠気の原因をATP不足・低酸素と判断することはできません。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC041', 'I041', '呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC042', 'I042', '「心拍数」と「R-R間隔」を別の量として表示する。軸名・単位・波形の向きを確認して図を差し替える。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC043', 'I043', '引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC044', 'I044', '等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC045', 'I045', '図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC046', 'I046', 'NREM睡眠をN1・N2・N3の3段階に整理する。図の配置と本文をまとめて更新する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC047', 'I047', '鼻の構造・NOの説明と、脳・免疫・いびき・睡眠への効果の主張を別に扱う。効能の矢印は根拠確認まで保留する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC048', 'I048', '呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC049', 'I049', '声は、呼吸・声帯・共鳴・発音などが関係して生まれます。胸や頭に感じる響きと、解剖学的な共鳴腔は区別して監修する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC050', 'I050', '「監修候補・未依頼」という制作メモとして保存する。教材本文やAIの回答に監修済みと表示しない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC051', 'I051', '八支則を意味する用語としてのアシュタンガと、現代の実践スタイルの名称を分け、歴史・用語の監修後に確定する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T01', '肺は自分の筋肉で動いているの？', '肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。', '肺の中に「呼吸筋」という固有の筋肉があるように説明しない。', '["K003"]', '["P02","P03","P037","P151","P152","P154","P155"]', '[]', '[{"passage_id":"P02","chapter":1,"label":"P4 4段階の見出しと説明","asset_id":"BM-CH01-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH01-A002.png"},{"passage_id":"P03","chapter":1,"label":"P4 換気・外呼吸・酸素運搬の説明","asset_id":"BM-CH01-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH01-A002.png"},{"passage_id":"P037","chapter":3,"label":"P12 原図表記は第2章","asset_id":"BM-CH03-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A003.png"},{"passage_id":"P151","chapter":2,"label":"P19 呼吸メカニズム","asset_id":"BM-CH02-A009","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH02-A009.png"},{"passage_id":"P152","chapter":3,"label":"P11 肺の動き","asset_id":"BM-CH03-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A001.png"},{"passage_id":"P154","chapter":3,"label":"P14 呼吸の力学","asset_id":"BM-CH03-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A005.png"},{"passage_id":"P155","chapter":3,"label":"P15 空気の流入","asset_id":"BM-CH03-A006","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A006.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T02', '横隔膜って何？', '横隔膜は胸とお腹を隔てる、ドーム状の筋肉です。息を吸うときに縮んで下がり、胸の中の空間を広げます。安静にして息を吐くときにはゆるみます。', '筋肉の名称と働きを具体的に説明する。', '["K026"]', '["P037","P150"]', '[]', '[{"passage_id":"P037","chapter":3,"label":"P12 原図表記は第2章","asset_id":"BM-CH03-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A003.png"},{"passage_id":"P150","chapter":2,"label":"P17 横隔膜","asset_id":"BM-CH02-A007","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH02-A007.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T03', '酸素がそのままATPになるの？', '酸素そのものがATPに変わるわけではありません。ATPは細胞がエネルギーをやり取りするための分子で、酸素は栄養から得たエネルギーを使ってATPをつくる過程を支えます。', '酸素とATPを同一視せず、未確認の産生量を付け足さない。', '["K006"]', '["P01","P04","P043","P165","P168"]', '[]', '[{"passage_id":"P01","chapter":1,"label":"図版2〜3 左上・右上・右中段","asset_id":"BM-CH01-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH01-A001.png"},{"passage_id":"P04","chapter":1,"label":"P5 上部・右側・下部ATP図","asset_id":"BM-CH01-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH01-A003.png"},{"passage_id":"P043","chapter":5,"label":"P33 ATPサイクル","asset_id":"BM-CH05-A004","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH05-A004.png"},{"passage_id":"P165","chapter":4,"label":"P26 酸素と細胞","asset_id":"BM-CH04-A009","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH04-A009.jpeg"},{"passage_id":"P168","chapter":5,"label":"P40 第5章まとめ","asset_id":"BM-CH05-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH05-A002.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T04', '呼吸数は少ないほどいいの？', '回数だけで良い・悪いは決めません。安静にして、いつも通りの呼吸を1分間数え、そのときの体調や状況と一緒に記録するための項目です。', '8回以下を高評価にするなどの採点をしない。', '["K011"]', '["P08"]', '[]', '[{"passage_id":"P08","chapter":1,"label":"P8 呼吸数セルフチェックと評価表","asset_id":"BM-CH01-A006","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH01-A006.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T05', 'SpO₂の数字だけで健康か分かる？', '数字だけでは判断しません。SpO₂は酸素とヘモグロビンの結び付きの割合を推定する指標で、測定には誤差や限界があります。症状や測定条件と合わせて扱います。', '章内で異なる数値区分を正常・受診基準として出さない。', '["K029"]', '["P041","P158"]', '[]', '[{"passage_id":"P041","chapter":4,"label":"P28 SpO₂","asset_id":"BM-CH04-A011","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH04-A011.png"},{"passage_id":"P158","chapter":4,"label":"第4章導入 酸素物流","asset_id":"BM-CH04-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH04-A001.jpeg"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T06', 'HRVは高いほど健康？', '高ければ必ず健康、低ければ必ず不調という意味ではありません。HRVは拍動の間隔のゆらぎで、呼吸・姿勢・活動・睡眠などの状況と一緒に見る項目です。', '健康度の一律採点や正常値の創作をしない。', '["K033"]', '["P047","P178","P185"]', '[]', '[{"passage_id":"P047","chapter":6,"label":"6-6 心拍変動","asset_id":"BM-CH06-A016","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH06-A016.png"},{"passage_id":"P178","chapter":6,"label":"6-13 検定ポイント","asset_id":"BM-CH06-A008","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH06-A008.png"},{"passage_id":"P185","chapter":6,"label":"6-7 呼吸と心拍","asset_id":"BM-CH06-A017","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH06-A017.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T07', 'プラーナは酸素のこと？', 'プラーナは、ヨガで生命エネルギーを表す伝統的な考え方です。酸素やATPと同じ物質を指す言葉としては扱いません。', '伝統的な概念と生理学的な物質を区別する。', '["K014"]', '["P15"]', '[]', '[{"passage_id":"P15","chapter":17,"label":"17-3 左側 学習テーマ・重要ポイント","asset_id":"BM-CH17-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A003.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T08', '八支則の中で呼吸はどこにある？', '教材の八支則では、呼吸を意識的に扱うプラーナーヤーマは4番目です。ヤマ、ニヤマ、アーサナに続き、その後にプラティヤハーラ、ダーラナー、ディヤーナ、サマーディが並びます。', '原稿の8要素の順序に沿い、医学的な効能に結び付けない。', '["K062"]', '["P077","P231"]', '[]', '[{"passage_id":"P077","chapter":16,"label":"16-1 八支則","asset_id":"BM-CH16-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH16-A002.png"},{"passage_id":"P231","chapter":16,"label":"第16章 八支則導入","asset_id":"BM-CH16-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH16-A001.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T09', '寝ている間は誰が呼吸を調整しているの？', '眠っている間の呼吸は主に自動調整されます。教材では、延髄や橋などによる呼吸の調整を説明しています。起きているときは、意識して呼吸を変えることもできます。', '意識していないと呼吸できない、睡眠中は絶対に止まらない、とは言わない。', '["K035","K080"]', '["P049","P193","P207"]', '[]', '[{"passage_id":"P049","chapter":7,"label":"7-2 呼吸中枢","asset_id":"BM-CH07-A011","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH07-A011.png"},{"passage_id":"P193","chapter":7,"label":"呼吸と脳のつながり","asset_id":"BM-CH07-A010","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH07-A010.png"},{"passage_id":"P207","chapter":8,"label":"8-2 睡眠中の呼吸","asset_id":"BM-CH08-A014","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A014.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T10', 'いびきがあると睡眠時無呼吸なの？', 'いびきだけで睡眠時無呼吸とは診断できません。教材では、呼吸が止まると言われる、強いいびきが続く、日中の強い眠気があるなどの場合に、医療機関への相談につなぐ方針です。', 'いびきから診断せず、教材の相談方針を併記する。', '["K081","K040"]', '["P210","P054","P199","P205"]', '["S004"]', '[{"passage_id":"P210","chapter":8,"label":"8-5 いびきとは","asset_id":"BM-CH08-A017","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A017.png"},{"passage_id":"P054","chapter":8,"label":"8-13 指導範囲と相談","asset_id":"BM-CH08-A007","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A007.png"},{"passage_id":"P199","chapter":8,"label":"8-10 朝の呼吸チェック","asset_id":"BM-CH08-A004","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A004.png"},{"passage_id":"P205","chapter":8,"label":"第2部 呼吸カルテ統合","asset_id":"BM-CH08-A011","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A011.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T11', '鼻が詰まっていても鼻呼吸を練習するの？', '鼻づまりなどで鼻呼吸がしにくいときは、無理に鼻呼吸だけを続けようとしません。教材では鼻の通りやいびきなどを確認し、必要な相談につなぐ方針です。自己判断で口閉じテープをすすめる手順も案内しません。', '鼻呼吸の強制や口閉じテープの手順を追加しない。', '["K082"]', '["P208","P209","P196"]', '["S004"]', '[{"passage_id":"P208","chapter":8,"label":"8-3 鼻呼吸と睡眠","asset_id":"BM-CH08-A015","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A015.png"},{"passage_id":"P209","chapter":8,"label":"8-4 口呼吸と睡眠","asset_id":"BM-CH08-A016","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A016.png"},{"passage_id":"P196","chapter":7,"label":"7-5 鼻呼吸と脳","asset_id":"BM-CH07-A014","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH07-A014.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T12', '疲れるのはATP不足だから？', '教材にはATPや酸素と体の働きの関係が出てきますが、疲れているということだけでATP不足や低酸素と決めることはできません。一般的な仕組みの説明と、本人の疲れの原因の判断は分けて考えます。', '症状から原因を断定しない。', '["K070"]', '["P159","P172","P211"]', '["S004"]', '[{"passage_id":"P159","chapter":4,"label":"P29 酸素不足","asset_id":"BM-CH04-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH04-A002.png"},{"passage_id":"P172","chapter":5,"label":"P39 エネルギー不足の連鎖","asset_id":"BM-CH05-A010","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH05-A010.jpeg"},{"passage_id":"P211","chapter":8,"label":"8-7 酸素不足と睡眠","asset_id":"BM-CH08-A019","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A019.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T13', 'NREM睡眠は4段階？', '第5版の説明では、NREM睡眠をN1・N2・N3の3段階に整理しています。元の図の4段階表示は、保存済みのNHLBI資料との照合に基づく修正対象です。', '元の図と修正後の分類を区別し、原図まで修正済みと言わない。', '["K079"]', '["P206"]', '[]', '[{"passage_id":"P206","chapter":8,"label":"8-1 睡眠とは何か","asset_id":"BM-CH08-A012","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A012.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T14', '声はお腹から出るの？', 'お腹から直接声が出るという意味ではありません。教材では、呼気による声帯の振動を基本として、呼吸や体の支えが声を支えると説明しています。声には共鳴や発音なども関係します。', '声の質のすべてを呼吸だけで説明しない。', '["K054","K055"]', '["P069","P223","P070"]', '[]', '[{"passage_id":"P069","chapter":13,"label":"13-1 声の仕組み","asset_id":"BM-CH13-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH13-A002.png"},{"passage_id":"P223","chapter":13,"label":"第13章導入","asset_id":"BM-CH13-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH13-A001.png"},{"passage_id":"P070","chapter":13,"label":"13-2 声の支え","asset_id":"BM-CH13-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH13-A003.jpeg"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T15', '第8章のやさしい4-7-8も7秒止めるの？', '第8章の「就寝前のやさしい呼吸」は保息なしの別手順です。名前だけを理由に7秒の息止めを付け足しません。保息の説明が曖昧な4-7-8呼吸のカードは、実践案内を保留しています。', '名称から保息を補完せず、別カードとして説明する。', '["C015","C007"]', '["P094","P24","P25","P26","P085"]', '["S002","S004"]', '[{"passage_id":"P094","chapter":8,"label":"8-9 やさしい版","asset_id":"BM-CH08-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A002.png"},{"passage_id":"P24","chapter":17,"label":"17-5 整理表の区分と教材での扱い","asset_id":"BM-CH17-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A005.png"},{"passage_id":"P25","chapter":17,"label":"17-5 現代呼吸法と他章接続の要約","asset_id":"BM-CH17-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A005.png"},{"passage_id":"P26","chapter":17,"label":"17-5 実践上の注意と選び方","asset_id":"BM-CH17-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A005.png"},{"passage_id":"P085","chapter":3,"label":"P19 4・7・8呼吸法","asset_id":"BM-CH03-A010","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH03-A010.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T16', '初心者だけどカパラバティは何回すればいい？', 'この教材では、初心者はカパラバティの特徴と注意点を学ぶ位置付けです。初心者向けの実践回数は案内しません。原稿の参考回数を、そのままあなたへの推奨回数にはしません。', '参考回数を初心者の推奨量に変換しない。', '["C005"]', '["P21","P22","P23","P24"]', '["S001","S004"]', '[{"passage_id":"P21","chapter":17,"label":"17-4 特徴・教材内での扱い","asset_id":"BM-CH17-A004","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A004.png"},{"passage_id":"P22","chapter":17,"label":"17-4 CYP記載として紹介される数値・禁忌","asset_id":"BM-CH17-A004","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A004.png"},{"passage_id":"P23","chapter":17,"label":"17-4 安全に行うための基本 第5部共通ルール","asset_id":"BM-CH17-A004","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A004.png"},{"passage_id":"P24","chapter":17,"label":"17-5 整理表の区分と教材での扱い","asset_id":"BM-CH17-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A005.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T17', 'ボックス呼吸は何セットに統一する？', '教材では第6章に4〜5サイクル、第7章に3〜5セットという違いがあります。別の章の数字を混ぜて統一せず、どの出典の手順かを明記します。保息を含むため、このDBでは個別の実践指示の自動配信を保留しています。', '出典差を明示。保管されている回数の比較と個別の実践指示を区別する。', '["C006"]', '["P24","P25","P26","P082","P083","P084","P187","P188","P186","P205"]', '["S002","S004"]', '[{"passage_id":"P24","chapter":17,"label":"17-5 整理表の区分と教材での扱い","asset_id":"BM-CH17-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A005.png"},{"passage_id":"P25","chapter":17,"label":"17-5 現代呼吸法と他章接続の要約","asset_id":"BM-CH17-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A005.png"},{"passage_id":"P26","chapter":17,"label":"17-5 実践上の注意と選び方","asset_id":"BM-CH17-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A005.png"},{"passage_id":"P082","chapter":6,"label":"6-10 実技6-2","asset_id":"BM-CH06-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH06-A005.png"},{"passage_id":"P083","chapter":7,"label":"7-10〜11","asset_id":"BM-CH07-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH07-A003.png"},{"passage_id":"P084","chapter":7,"label":"7-11 やさしい版","asset_id":"BM-CH07-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH07-A003.png"},{"passage_id":"P187","chapter":7,"label":"7-9〜7-11 ボックス呼吸","asset_id":"BM-CH07-A002","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH07-A002.png"},{"passage_id":"P188","chapter":7,"label":"7-12 本番前コントロール","asset_id":"BM-CH07-A004","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH07-A004.png"},{"passage_id":"P186","chapter":7,"label":"第7章導入","asset_id":"BM-CH07-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH07-A001.jpeg"},{"passage_id":"P205","chapter":8,"label":"第2部 呼吸カルテ統合","asset_id":"BM-CH08-A011","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A011.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T18', '1分間6呼吸なら5秒吸って5秒吐けばいい？', '回数だけから吸う・吐く時間の配分は決められません。この教材の一覧には「1分間6呼吸」と実施時間が載っていますが、吸気と呼気の比率や保息の有無は未記載です。5秒ずつという手順は補いません。', '未記載の秒数・保息を計算で推定しない。', '["C034"]', '["P205"]', '["S002","S004"]', '[{"passage_id":"P205","chapter":8,"label":"第2部 呼吸カルテ統合","asset_id":"BM-CH08-A011","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH08-A011.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T19', '食前の休息呼吸？ 食後の休息呼吸？', '第5版では「食後の休息呼吸」としています。元原稿の一部見出しは食前ですが、本文と第10章一覧の食後に合わせて整理しました。食前の整え呼吸とは分けて扱います。', '正式な編集後名称を使い、原図の見出しの違いも説明できる。', '["C026","K047"]', '["P105","P106","P120","P062"]', '["S004"]', '[{"passage_id":"P105","chapter":10,"label":"10-4 実践2（見出し表記差あり）","asset_id":"BM-CH10-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH10-A005.png"},{"passage_id":"P106","chapter":10,"label":"第10章 呼吸法整理","asset_id":"BM-CH10-A006","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH10-A006.png"},{"passage_id":"P120","chapter":11,"label":"第11章 正式名称と置換表","asset_id":"BM-CH11-A007","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH11-A007.png"},{"passage_id":"P062","chapter":10,"label":"10-4 食事と呼吸","asset_id":"BM-CH10-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH10-A005.png"}]') ON CONFLICT (test_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_acceptance_tests (test_id, question, answer_example, check_point, reference_entry_ids, source_passage_ids, safety_ids, source_links) VALUES ('T20', 'シータリーは引用先のCYPに必ず載っている？', '教材が引用するCYPの版では、掲載を確認できていないため、載っているとは断定しません。別の版を根拠にする場合は、版・ページを特定して照合する必要があります。', '教材のCYP準拠という記載を全技法の掲載証明にしない。', '["K019"]', '["P19","P24","P229"]', '[]', '[{"passage_id":"P19","chapter":17,"label":"17-3 シートカーリー補足","asset_id":"BM-CH17-A003","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A003.png"},{"passage_id":"P24","chapter":17,"label":"17-5 整理表の区分と教材での扱い","asset_id":"BM-CH17-A005","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH17-A005.png"},{"passage_id":"P229","chapter":15,"label":"第5部導入","asset_id":"BM-CH15-A001","path":"../YogaAI_回答用DB_全17章_v5/assets/BM-CH15-A001.jpeg"}]') ON CONFLICT (test_id) DO NOTHING;
